def recursive_list_sum(lst):
    """
    Recursively flattens a nested list and returns the sum of all its elements.

    :param lst: List of integers or nested lists of integers
    :return: Integer sum of all elements in the list
    """
    if not lst:
        return 0
    elif isinstance(lst[0], list):
        return recursive_list_sum(lst[0]) + recursive_list_sum(lst[1:])
    else:
        return lst[0] + recursive_list_sum(lst[1:])
